if (!defined('CLI_SCRIPT')) { define('CLI_SCRIPT', true); }
require('/www/moodle/config.php');
require_once($CFG->dirroot . '/lib/questionlib.php');
require_once($CFG->dirroot . '/question/format/xml/format.php');
require_once($CFG->dirroot . '/mod/quiz/lib.php');
require_once($CFG->dirroot . '/mod/quiz/locallib.php');
try {
    global $DB, $USER;
    $USER = get_admin();

    $course = $DB->get_record('course', ['shortname' => 'GAPFILL01']);
    if (!$course) {
        throw new \RuntimeException("Course 'GAPFILL01' was not found.");
    }

    $questionbanks = $DB->get_records('qbank', ['course' => $course->id]);
    if (count($questionbanks) !== 1) {
        throw new \RuntimeException("Expected one question bank for course 'GAPFILL01'; found " . count($questionbanks) . '.');
    }
    $questionbank = reset($questionbanks);
    $questionbankcm = get_coursemodule_from_instance('qbank', $questionbank->id, $course->id);
    if (!$questionbankcm) {
        throw new \RuntimeException("The course-module record for the 'GAPFILL01' question bank was not found.");
    }
    $questionbankcontext = context_module::instance($questionbankcm->id);
    $category = question_get_default_category($questionbankcontext->id, true);
    if (!$category) {
        throw new \RuntimeException("The default question category for course 'GAPFILL01' was not found or created.");
    }

    $findquestion = static function (string $name) use ($DB, $category) {
        $sql = "SELECT q.*
                  FROM {question} q
                  JOIN {question_versions} qv ON qv.questionid = q.id
                  JOIN {question_bank_entries} qbe ON qbe.id = qv.questionbankentryid
                 WHERE qbe.questioncategoryid = :categoryid
                   AND q.qtype = :qtype
                   AND q.name = :name
              ORDER BY qv.version DESC, q.id DESC";
        $questions = $DB->get_records_sql($sql, [
            'categoryid' => $category->id,
            'qtype' => 'gapfill',
            'name' => $name,
        ], 0, 2);
        if (count($questions) > 1) {
            throw new \RuntimeException("More than one '{$name}' Gapfill question exists in the target category.");
        }
        return $questions ? reset($questions) : false;
    };

    $importquestion = static function (string $xml) use ($category, $questionbankcontext, $course) {
        $tmpdir = make_request_directory();
        $tmpfile = $tmpdir . '/gapfill.xml';
        if (file_put_contents($tmpfile, $xml) === false) {
            throw new \RuntimeException('Could not write the temporary Gapfill question import file.');
        }
        $qformat = new qformat_xml();
        $qformat->setCategory($category);
        $qformat->setContexts([$questionbankcontext]);
        $qformat->setCourse($course);
        $qformat->setFilename($tmpfile);
        $qformat->setMatchgrades('error');
        $qformat->setCatfromfile(false);
        $qformat->setContextfromfile(false);
        $qformat->setStoponerror(true);
        $qformat->set_display_progress(false);
        ob_start();
        try {
            $imported = $qformat->importpreprocess()
                && $qformat->importprocess()
                && $qformat->importpostprocess();
        } finally {
            ob_end_clean();
        }
        if (!$imported || count($qformat->questionids) !== 1) {
            throw new \RuntimeException('Moodle XML import did not create exactly one Gapfill question.');
        }
        return (int) reset($qformat->questionids);
    };

    // Three demo questions, one per Gapfill display mode. Each has two gaps => 2 marks.
    $questiondefs = [
        'gapfill-001' => <<<'GAPFILLXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
  <question type="gapfill">
    <name><text>gapfill-001</text></name>
    <questiontext format="html">
      <text><![CDATA[<p>Drag-and-drop mode: drag each word into the correct gap.</p><p>The [cat] sat on the [mat].</p>]]></text>
    </questiontext>
    <generalfeedback format="html">
      <text><![CDATA[<p>Well done!</p>]]></text>
    </generalfeedback>
    <defaultgrade>2.0000000</defaultgrade>
    <penalty>0.3333333</penalty>
    <hidden>0</hidden>
    <idnumber></idnumber>
    <answerdisplay>dragdrop</answerdisplay>
    <delimitchars>[]</delimitchars>
    <casesensitive>0</casesensitive>
    <noduplicates>0</noduplicates>
    <disableregex>0</disableregex>
    <fixedgapsize>0</fixedgapsize>
    <optionsaftertext>0</optionsaftertext>
    <answer fraction="100" format="moodle_auto_format"><text>cat</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
    <answer fraction="100" format="moodle_auto_format"><text>mat</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
    <answer fraction="0" format="moodle_auto_format"><text>dog</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
    <answer fraction="0" format="moodle_auto_format"><text>rug</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
  </question>
</quiz>
GAPFILLXML,
        'gapfill-002' => <<<'GAPFILLXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
  <question type="gapfill">
    <name><text>gapfill-002</text></name>
    <questiontext format="html">
      <text><![CDATA[<p>Dropdown mode: choose each answer from the list.</p><p>The sun rises in the [east] and sets in the [west].</p>]]></text>
    </questiontext>
    <generalfeedback format="html">
      <text><![CDATA[<p>Well done!</p>]]></text>
    </generalfeedback>
    <defaultgrade>2.0000000</defaultgrade>
    <penalty>0.3333333</penalty>
    <hidden>0</hidden>
    <idnumber></idnumber>
    <answerdisplay>dropdown</answerdisplay>
    <delimitchars>[]</delimitchars>
    <casesensitive>0</casesensitive>
    <noduplicates>0</noduplicates>
    <disableregex>0</disableregex>
    <fixedgapsize>0</fixedgapsize>
    <optionsaftertext>0</optionsaftertext>
    <answer fraction="100" format="moodle_auto_format"><text>east</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
    <answer fraction="100" format="moodle_auto_format"><text>west</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
    <answer fraction="0" format="moodle_auto_format"><text>north</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
    <answer fraction="0" format="moodle_auto_format"><text>south</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
  </question>
</quiz>
GAPFILLXML,
        'gapfill-003' => <<<'GAPFILLXML'
<?xml version="1.0" encoding="UTF-8"?>
<quiz>
  <question type="gapfill">
    <name><text>gapfill-003</text></name>
    <questiontext format="html">
      <text><![CDATA[<p>Text-entry mode: type each answer.</p><p>Water is made of [hydrogen] and [oxygen].</p>]]></text>
    </questiontext>
    <generalfeedback format="html">
      <text><![CDATA[<p>Well done!</p>]]></text>
    </generalfeedback>
    <defaultgrade>2.0000000</defaultgrade>
    <penalty>0.3333333</penalty>
    <hidden>0</hidden>
    <idnumber></idnumber>
    <answerdisplay>gapfill</answerdisplay>
    <delimitchars>[]</delimitchars>
    <casesensitive>0</casesensitive>
    <noduplicates>0</noduplicates>
    <disableregex>0</disableregex>
    <fixedgapsize>0</fixedgapsize>
    <optionsaftertext>0</optionsaftertext>
    <answer fraction="100" format="moodle_auto_format"><text>hydrogen</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
    <answer fraction="100" format="moodle_auto_format"><text>oxygen</text><feedback format="moodle_auto_format"><text></text></feedback></answer>
  </question>
</quiz>
GAPFILLXML,
    ];

    $questionids = [];
    foreach ($questiondefs as $name => $xml) {
        $question = $findquestion($name);
        if (!$question) {
            $newid = $importquestion($xml);
            $question = $findquestion($name);
            if (!$question || (int) $question->id !== $newid) {
                throw new \RuntimeException("The imported '{$name}' question could not be retrieved from its category.");
            }
        }
        $questionids[$name] = (int) $question->id;
    }

    $quizzes = $DB->get_records('quiz', ['course' => $course->id, 'name' => 'Testing Gapfill!']);
    if (count($quizzes) !== 1) {
        throw new \RuntimeException("Expected one quiz named 'Testing Gapfill!' in course 'GAPFILL01'; found " . count($quizzes) . '.');
    }
    $quiz = reset($quizzes);
    $quizcm = get_coursemodule_from_instance('quiz', $quiz->id, $course->id);
    if (!$quizcm) {
        throw new \RuntimeException("The course-module record for quiz 'Testing Gapfill!' was not found.");
    }
    $quiz->cmid = $quizcm->id;
    $quiz->cmidnumber = $quizcm->idnumber ?? '';

    if ((int) $quiz->cmid !== 2) {
        throw new \RuntimeException("Quiz 'Testing Gapfill!' must have course-module ID 2 for the configured landing page; found {$quiz->cmid}.");
    }

    // The declarative addModule step inserts the quiz record directly and never
    // creates the initial quiz_sections row that quiz_add_instance() provides;
    // quiz_start_new_attempt() requires it to build the attempt layout.
    if (!$DB->record_exists('quiz_sections', ['quizid' => $quiz->id])) {
        $DB->insert_record('quiz_sections', (object) ['quizid' => $quiz->id, 'firstslot' => 1, 'heading' => '', 'shufflequestions' => 0]);
    }

    foreach ($questionids as $name => $qid) {
        $questionbankentry = get_question_bank_entry($qid);
        $assignedcount = $DB->count_records_sql(
            "SELECT COUNT(1)
               FROM {quiz_slots} slot
               JOIN {question_references} qr ON qr.itemid = slot.id
              WHERE slot.quizid = :quizid
                AND qr.component = :component
                AND qr.questionarea = :questionarea
                AND qr.questionbankentryid = :questionbankentryid",
            [
                'quizid' => $quiz->id,
                'component' => 'mod_quiz',
                'questionarea' => 'slot',
                'questionbankentryid' => $questionbankentry->id,
            ]
        );
        if ($assignedcount > 1) {
            throw new \RuntimeException("The '{$name}' question is assigned to the quiz more than once.");
        }
        if ($assignedcount === 0) {
            quiz_add_quiz_question($qid, $quiz, 0, 2);
        }
    }

    $quizsettings = \mod_quiz\quiz_settings::create($quiz->id);
    $quizsettings->get_grade_calculator()->recompute_quiz_sumgrades();
    $quiz = $DB->get_record('quiz', ['id' => $quiz->id]);
    if (!$quiz || (float) $quiz->sumgrades !== 6.0 || (float) $quiz->grade !== 6.0) {
        throw new \RuntimeException('Quiz grade and sum-of-grades must both equal 6.');
    }
    $quiz->cmid = $quizcm->id;
    $quiz->cmidnumber = $quizcm->idnumber ?? '';
    quiz_update_grades($quiz);

    echo "Provisioned quiz 'Testing Gapfill!' with 3 Gapfill questions at cmid={$quiz->cmid}.\n";
} catch (\Throwable $e) {
    fwrite(STDERR, 'Gapfill quiz provisioning failed: ' . $e->getMessage() . "\n");
}
